export function formatCSSLength(length?: number | string | null) {
  if (typeof length === 'string') {
    if (!isNaN(Number(length))) {
      return `${length}px`;
    }
    return length;
  } else if (typeof length === 'number') {
    return `${length}px`;
  }
  return;
}

export function parseCSSLength(length: string | number = 0): number {
  if (typeof length === 'number') {
    return length;
  } else {
    if (length?.endsWith('px')) {
      return Number(length.replace('px', ''));
    }
    return Number(length);
  }
}
